CREATE TABLE miniapps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),actor_id uuid NOT NULL REFERENCES world_characters(id) DEFERRABLE,title text NOT NULL,language text NOT NULL CHECK(language IN ('html','python')),source text NOT NULL,resources jsonb NOT NULL DEFAULT '{}',revision integer NOT NULL DEFAULT 1,run_enabled boolean NOT NULL DEFAULT false,persistence boolean NOT NULL DEFAULT true,ai_state text NOT NULL DEFAULT 'none' CHECK(ai_state IN ('none','read','write')),state jsonb NOT NULL DEFAULT '{}',state_revision integer NOT NULL DEFAULT 0);
CREATE TABLE runtime_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),app_id uuid NOT NULL REFERENCES miniapps(id),app_revision integer NOT NULL,principal text NOT NULL CHECK(principal IN ('owner','ai')),state_revision integer NOT NULL,network jsonb NOT NULL DEFAULT '[]',result jsonb,error_code text,status text NOT NULL DEFAULT 'open',expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes');
CREATE UNIQUE INDEX runtime_one_execution ON runtime_sessions(app_id) WHERE status='executing';
CREATE TABLE runtime_conflicts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),owner_id uuid NOT NULL REFERENCES owners(id),app_id uuid NOT NULL REFERENCES miniapps(id) DEFERRABLE,base_revision integer NOT NULL,state jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
